/** Actual player surface motion/jump/seat input, animal capture, save/unload and world-seat handoff. */
final class ContraptionCollisionRenderingTest {
    private static final BlockPos P=new BlockPos(3615,5,5),B=P.below(),SEAT=P.east(2).above();
    private static final BlockPos LOCAL_SEAT=new BlockPos(2,1,0);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 3615.5 10 13.5");context.waitFor(client->Math.abs(client.player.getX()-3615.5)<.1&&client.level.isLoaded(P)&&client.level.isLoaded(SEAT),400);
        server.runCommand("fill 3609 3 -1 3623 3 13 minecraft:smooth_quartz");server.runCommand("setblock 3615 4 5 create:mechanical_bearing[facing=up]");server.runCommand("fill 3614 5 4 3616 5 6 minecraft:stone");server.runCommand("setblock 3617 5 5 minecraft:stone");server.runCommand("setblock 3617 6 5 create:red_seat");
        NativeContraptionFixtures.awaitEntityReady(context,world,300,P,SEAT);
        var pigId=new AtomicReference<UUID>();var ownerId=new AtomicReference<UUID>();
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var pig=EntityTypes.PIG.create(level,EntitySpawnReason.COMMAND);pig.setNoAi(true);pig.setPersistenceRequired();pig.setPos(SEAT.getX()+.5,SEAT.getY()+1,SEAT.getZ()+.5);level.addFreshEntity(pig);NativeContraptionFixtures.sitDown(level,SEAT,pig);if(!(pig.getVehicle() instanceof SeatEntity))throw new AssertionError("Fixture animal failed to sit on world seat: nativeReady="+com.simibubi.create.foundation.utility.LoadedEntityAccess.isReady(level,SEAT)+", entityTicking="+level.isPositionEntityTicking(SEAT)+", passengerRegistered="+(level.getEntity(pig.getUUID())==pig)+", originalUuid="+pig.getUUID()+", seat="+level.getBlockState(SEAT)+", actualVehicle="+pig.getVehicle());pigId.set(pig.getUUID());level.addFreshEntity(new SuperGlueEntity(level,SuperGlueEntity.span(P.offset(-1,0,-1),SEAT.south())));var player=level.getServer().getPlayerList().getPlayers().getFirst();player.getInventory().clearContent();player.inventoryMenu.broadcastFullState();});
        server.runCommand("setblock 3615 3 5 create:creative_motor[facing=up]");var ready=new AtomicBoolean();
        for(int i=0;i<300&&!ready.get();i++){server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var bearing=(MechanicalBearingBlockEntity)level.getBlockEntity(B);var owner=bearing.getMovedContraption();if(owner!=null&&owner.getContraption()!=null&&level.getEntity(pigId.get()).getVehicle()==owner){if(owner.getContraption().getBlocks().size()!=11)throw new AssertionError("Fixture platform structure incomplete");ownerId.set(owner.getUUID());ready.set(true);}});if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError("Actual bearing did not take seated animal with platform");
        context.waitFor(client->find(client.level,ownerId.get()) instanceof ControlledContraptionEntity owner&&owner.getContraption()!=null&&find(client.level,pigId.get())!=null&&find(client.level,pigId.get()).getVehicle()==owner,400);
        world.getConnection().waitForChunksRender();look(context,Vec3.atCenterOf(P));screenshot(context,"create-vulkan-collision-seated-animal-capture");
        server.runCommand("tp @p 3616.5 6 5.5");server.runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&client.player.onGround()&&Math.abs(client.player.getY()-6)<.05,300);
        var before=context.computeOnClient(client->client.player.position());context.waitTicks(100);
        context.runOnClient(client->{var owner=(ControlledContraptionEntity)find(client.level,ownerId.get());double radius=Math.hypot(client.player.getX()-P.getX()-.5,client.player.getZ()-P.getZ()-.5);if(Math.abs(client.player.getY()-6)>.05||radius<.75||radius>1.25||client.player.position().distanceTo(before)<.5||!owner.collidingEntities.containsKey(client.player))throw new AssertionError("Real standing player did not remain on rotating surface: pos="+client.player.position()+" radius="+radius);});
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var owner=(ControlledContraptionEntity)level.getEntity(ownerId.get());var player=level.getServer().getPlayerList().getPlayers().getFirst();if(Math.abs(player.getY()-6)>.15||player.fallDistance>1||!owner.collidingEntities.containsKey(player))throw new AssertionError("Server did not verify actual moving support: pos="+player.position()+" velocity="+player.getDeltaMovement()+" fall="+player.fallDistance+" contact="+owner.collidingEntities.get(player)+" eligible="+owner.canCollideWith(player)+" angle="+owner.getAngle(1));});look(context,Vec3.atCenterOf(P));screenshot(context,"create-vulkan-collision-player-standing");
        context.getInput().holdKey(options->options.keyJump);
        context.waitFor(client->client.player.getY()>6.15,100);
        context.getInput().releaseKey(options->options.keyJump);
        context.waitFor(client->client.player.onGround()&&Math.abs(client.player.getY()-6)<.06,200);look(context,Vec3.atCenterOf(P));var radiusBefore=context.computeOnClient(client->Math.hypot(client.player.getX()-P.getX()-.5,client.player.getZ()-P.getZ()-.5));context.getInput().holdKey(options->options.keyUp);context.waitTicks(3);context.getInput().releaseKey(options->options.keyUp);context.waitTicks(3);context.runOnClient(client->{double radius=Math.hypot(client.player.getX()-P.getX()-.5,client.player.getZ()-P.getZ()-.5);if(Math.abs(client.player.getY()-6)>.07||radius>=radiusBefore-.03)throw new AssertionError("Player input cannot walk on moving floor");});screenshot(context,"create-vulkan-collision-player-jump-walk");
        var seatTarget=context.computeOnClient(client->((ControlledContraptionEntity)find(client.level,ownerId.get())).toGlobalVector(new Vec3(2.5,1.25,.5),1));look(context,seatTarget);context.waitTicks(1);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.player.getVehicle() instanceof ControlledContraptionEntity owner&&owner.getUUID().equals(ownerId.get()),300);context.waitTicks(5);
        var yaw=context.computeOnClient(client->client.player.getYRot());var angle=context.computeOnClient(client->((ControlledContraptionEntity)client.player.getVehicle()).getAngle(1));context.waitTicks(15);
        context.runOnClient(client->{var owner=(ControlledContraptionEntity)client.player.getVehicle();var expected=owner.getPassengerPosition(client.player,1).add(0,SeatEntity.getCustomEntitySeatOffset(client.player)-.125,0);if(client.player.position().distanceTo(expected)>.05)throw new AssertionError("Native seated player attachment is detached from moving seat");float delta=Mth.wrapDegrees(owner.getAngle(1)-angle),camera=Mth.wrapDegrees(yaw-client.player.getYRot());if(Math.abs(Mth.wrapDegrees(delta-camera))>10)throw new AssertionError("Default seated camera rotation differs from platform: "+delta+"/"+camera);});screenshot(context,"create-vulkan-collision-player-seated");
        context.getInput().holdKey(options->options.keyShift);context.waitFor(client->!client.player.isPassenger(),200);context.getInput().releaseKey(options->options.keyShift);context.waitTicks(5);context.runOnClient(client->{var owner=(ControlledContraptionEntity)find(client.level,ownerId.get());if(client.player.position().distanceTo(owner.toGlobalVector(new Vec3(2.5,1.25,.5),1))>3)throw new AssertionError("Dismount teleported player away from real seat");});screenshot(context,"create-vulkan-collision-player-dismounted");
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 3615.5 10 13.5");server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((MechanicalBearingBlockEntity)level.getBlockEntity(B)).setMovementMode(IControlContraption.RotationMode.ROTATE_NEVER_PLACE);((com.simibubi.create.content.kinetics.base.KineticBlockEntity)level.getBlockEntity(B.below())).setGeneratedSpeed(0);});context.waitTicks(8);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var owner=(ControlledContraptionEntity)level.getEntity(ownerId.get());var pig=(net.minecraft.world.entity.Mob)level.getEntity(pigId.get());pig.setNoAi(false);pig.removeFreeWill();pig.setNoGravity(false);pig.setPos(owner.toGlobalVector(new Vec3(2.5,2.25,.5),1));pig.setDeltaMovement(Vec3.ZERO);});
        var captured=new AtomicBoolean();for(int i=0;i<160&&!captured.get();i++){context.waitTicks(1);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();captured.set(level.getEntity(pigId.get()).getVehicle()==level.getEntity(ownerId.get()));});}if(!captured.get())throw new AssertionError("Real falling animal was not picked up by moving seat collision");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((com.simibubi.create.content.kinetics.base.KineticBlockEntity)level.getBlockEntity(B.below())).setGeneratedSpeed(16);});context.waitTicks(5);screenshot(context,"create-vulkan-collision-animal-auto-capture");
        server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();for(int i=0;i<160&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();unloaded.set(level.getEntity(ownerId.get())==null&&level.getEntity(pigId.get())==null&&level.getChunkSource().getChunkNow(P.getX()>>4,0)==null&&level.getChunkSource().getChunkNow(SEAT.getX()>>4,0)==null);});}if(!unloaded.get())throw new AssertionError("Seat/collision state retained actual source chunks");
        server.runCommand("tp @p 3615.5 10 13.5");context.waitFor(client->find(client.level,ownerId.get()) instanceof ControlledContraptionEntity owner&&owner.getContraption()!=null&&find(client.level,pigId.get())!=null&&find(client.level,pigId.get()).getVehicle()==owner,600);world.getConnection().waitForChunksRender();look(context,Vec3.atCenterOf(P));context.waitTicks(5);screenshot(context,"create-vulkan-collision-passenger-unload-return");
        server.runCommand("tp @p 3615.5 4 9.5");server.runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&Math.abs(client.player.getZ()-9.5)<.1,200);look(context,Vec3.atCenterOf(B));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(B),200);context.waitTicks(4);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->find(client.level,ownerId.get())==null&&find(client.level,pigId.get())!=null&&find(client.level,pigId.get()).getVehicle() instanceof SeatEntity,300);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var pig=level.getEntity(pigId.get());if(!(pig.getVehicle() instanceof SeatEntity seat)||!(level.getBlockState(seat.blockPosition()).getBlock() instanceof SeatBlock))throw new AssertionError("Disassembly did not restore real world passenger seat");});look(context,Vec3.atCenterOf(P));screenshot(context,"create-vulkan-collision-passenger-world-restoration");server.runCommand("gamemode spectator @p");
    }
    private static Entity find(net.minecraft.client.multiplayer.ClientLevel level,UUID uuid){if(level==null)return null;for(var entity:level.entitiesForRendering())if(entity.getUUID().equals(uuid))return entity;return null;}
    private static void screenshot(ClientGameTestContext context,String name){context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot(name);}
    private static void look(ClientGameTestContext context,Vec3 point){var angles=context.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(angles.x,angles.y);}
}
